from __future__ import annotations

from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class APC(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type APC"""

    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 10,
        snmp_user: dict[str, Any] | None = None,
        num_of_ports: int = 8,
        community: str = "private",
    ):
        """
        :param string host: IP address or domain name of the APC device.
        :param float timeout: Response timeout in seconds, default value is 10
        :param dict snmp_user (required only for SNMPv3): User configuration for SNMPv3 with keys: userName, authKey,
                          privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
        :param int num_of_ports: number of ports of pdu, default is 8
        :param community: Community string used by SNMPv1/2.
        """
        super(APC, self).__init__(host, timeout, snmp_user, community)
        self.num_of_ports = int(num_of_ports)
        self._version = 1
        self._key = "1.3.6.1.4.1.318.1.1.12.3.3.1.1.4"

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: "1", DeviceStatus.OFF: "2"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port):
        if port in range(1, self.num_of_ports + 1):
            return f"{self._key}.{port}"
        else:
            raise BadPortNumber(f"Port number is invalid: {port}")


class APC_AP7922B(APC):
    def __init__(self, host, timeout=10, snmp_user=None, num_of_ports=16, community="private"):
        super(APC_AP7922B, self).__init__(
            host=host,
            timeout=timeout,
            num_of_ports=num_of_ports,
            snmp_user=snmp_user,
            community=community,
        )
